"},{"name":"Use Node.js","uses":"actions/setup-node@v4","with":{"cache":"npm","node-version":"20.x"}},{"name":"Validate changelog version matches environment files","run":"node <<'EOF'
const fs = require('node:fs');
const path = require('node:path');

const changelogPath = path.join(process.cwd(), 'CHANGELOG.md');
const environmentsDir = path.join(process.cwd(), 'src', 'environments');

const changelog = fs.readFileSync(changelogPath, 'utf8');
const latestVersionMatch = changelog.match(/^##\s+(\d+\.\d+\.\d+)\s*$/m);

if (!latestVersionMatch) {
  console.error(`Could not determine the latest version from ${changelogPath}.`);
  process.exit(1);
}

const latestVersion = latestVersionMatch[1];
const environmentFiles = fs
  .readdirSync(environmentsDir)
  .filter((file) => /^environment.*\.ts$/.test(file))
  .sort();

const mismatches = [];

for (const file of environmentFiles) {
  const filePath = path.join(environmentsDir, file);
  const contents = fs.readFileSync(filePath, 'utf8');
  const versionMatch = contents.match(/version:\s*['"]([^'"]+)['"]/);

  if (!versionMatch) {
    mismatches.push(`${file}: missing version`);
    continue;
  }

  const fileVersion = versionMatch[1];

  if (fileVersion !== latestVersion) {
    mismatches.push(`${file}: ${fileVersion}`);
  }
}

if (mismatches.length > 0) {
  console.error(`Latest changelog version: ${latestVersion}`);
  console.error('Environment version mismatches found:');
  for (const mismatch of mismatches) {
    console.error(`- ${mismatch}`);
  }
  process.exit(1);
}

console.log(`Environment versions match changelog version ${latestVersion}.`);
EOF
